// Block drop: a falling-block puzzle. Shapes of four cells fall into a well
// ten wide and twenty deep; turn and slide them so they fill rows, and a
// full row clears. Drawn a byte a cell in the 8-bit palette mode
// (frameos.pixels): the well remembers what each of its cells shows and a
// frame rewrites only the cells that changed.
//
// On the screen: left, right, down (faster) and drop (all the way) on the
// left; turn and keep on the right. Keys: the arrows or WASD, Up / X / K
// turn, Z turns back, Space drops, C or Shift keeps, P pauses. On e-paper the
// pieces fall only when you say so: every press moves or turns, and Down
// lowers the piece one row, a slow puzzle; with the frame's buttons,
// pressing LEFT and RIGHT together turns.
import { rect } from './gfx'
import { drawText, textWidth } from './font'
import { L, layout, drawControls, updateControls } from './layout'
import { UI, GAME, familyColors, FAMILY_DARK, fillPalette, mix } from './palette'
import { input, held, consume, takeEvent, setButtonMap, nameAction, mapKey, releaseAll, LEFT, RIGHT, UP, DOWN, A, B, C, PAUSE } from './input'
import { stepsDue, restartClock, setSeed, getSeed, rand, readSettings, highContrast, readScores, placeScore } from './core'
import { drawCard, cardKeyAt, scoreLines, drawHudBar, hudField, hudSlots, HUD } from './card'
import { CELL_X, CELL_Y, KICK_X, KICK_Y, GRAVITY } from './pieces'

nameAction('rotate', A)
nameAction('turn', A)
nameAction('rotateback', B)
nameAction('hold', C)
nameAction('drop', UP)
nameAction('start', A)
// The usual keys for this kind of game: Up turns, Space drops all the way.
mapKey('ArrowUp', A)
mapKey('KeyW', A)
mapKey('KeyX', A)
mapKey('KeyK', A)
mapKey('KeyZ', B)
mapKey('KeyJ', B)
mapKey('Space', UP)
mapKey('KeyC', C)
mapKey('ShiftLeft', C)
mapKey('ShiftRight', C)

// --- the palette ---
const WELL_BG = GAME
const WELL_DOT = GAME + 1
const WELL_EDGE = GAME + 2
const WELL_EDGE_HI = GAME + 3
const GHOST = GAME + 4
const FLASH = GAME + 5
const PANEL_INK = GAME + 6
const BLOCK = GAME + 8 // seven shapes, three each: fill, light edge, dark edge

const PIECE_COLORS = [0x3dd6d0, 0xffd43b, 0xb57cf5, 0x6fdc6f, 0xff6b6b, 0x5c8df6, 0xffa94d]
const COLORS = familyColors(0x161226, 0xb57cf5, 0x3dd6d0).concat([
  0x0f0c1c, 0x2a2440, 0x4b4170, 0x7a6cb0, 0x8a80b0, 0xffffff, 0x8590a6, 0,
])
for (const color of PIECE_COLORS) COLORS.push(color, mix(color, 0xffffff, 120), mix(color, 0x000000, 100))
// High contrast: white well, black pieces with a white line along their top and left, the ghost an outline.
const DARK = FAMILY_DARK.concat([0, 0, 1, 1, 1, 1, 1, 0])
for (let i = 0; i < 7; i++) DARK.push(1, 0, 1)

const SETTINGS = ['contrast', 'pixelSize', 'controls', 'buttons', 'ghost', 'previews', 'hold', 'startLevel']
const DEFAULT_BUTTONS = 'LEFT=left, RIGHT=right, UP=drop, DOWN=down, A=left, B=right, C=rotate, D=down, ' +
  'KEY0=left, KEY1=right, BOOT=rotate, REFRESH=down, OK=rotate, ENTER=rotate, SELECT=hold, primary=rotate, next=right, prev=left, up=drop, down=down, back=hold, menu=pause, refresh=down'

// --- the screen ---
let cells: Uint8Array | null = null
const palette = new Uint32Array(256)
let screenKey = ''
let fast = true
let high = false
let width = 0
let height = 0
let envAt = -1e9
let settings: Record<string, any> = {}
let frameColor: any = true
let mode = 'title' // title, play, clear, pause, over
let modeSteps = 0
let redraw = true
let scores: number[] = []
let rank = -1
let idleSince = 0

// --- the well: 10 x 22 cells, the top two hidden ---
const W = 10
const H = 22
const TOP = 2
const board = new Uint8Array(W * H) // 0 empty, 1-7 a shape's color
const shown = new Int16Array(W * (H - TOP)) // what each visible cell shows now: -1 nothing yet
const want = new Int16Array(W * (H - TOP))
let b = 4 // a cell of the well, in cells of the picture
let mb = 2 // a cell of the previews
let wx = 0 // the well's inside, top left
let wy = 0
let px = 0 // the panel beside it
let panelW = 0

// --- the game ---
let piece = 0
let rot = 0
let x = 3
let y = 1
let holdPiece = -1
let holdUsed = false
const queue: number[] = []
let bag = ''
let score = 0
let lines = 0
let level = 1
let startLevel = 1
let fallAcc = 0
let lockSteps = 0
let lockMoves = 0
let dasLeft = 0
let dasRight = 0
let clearing = 0 // rows being cleared, as bits from the top
let dirty = true // the well must be worked out again
let panelDirty = true
let gameSeed = 1
let snapAt = 0
let pending = 0 // presses not acted on yet: a frame can come before a step is due
let ghostOn = true
let holdOn = true
let previews = 3

function env(app: any, context: any, now: number, force: boolean): boolean {
  if (!force && now - envAt < 1000) return false
  envAt = now
  const frame = app.frame
  width = (context && context.imageWidth) || width || frame.width
  height = (context && context.imageHeight) || height || frame.height
  fast = frame.fast ?? !frame.paper
  frameColor = frame.color
  settings = readSettings(app, SETTINGS, now, true)
  setButtonMap(settings.buttons || DEFAULT_BUTTONS)
  high = highContrast(settings.contrast, frameColor)
  ghostOn = settings.ghost !== 'off'
  holdOn = settings.hold !== 'off'
  previews = Math.max(1, Math.min(3, Number(settings.previews) || 3))
  return true
}

function controlsOn(): boolean {
  const c = settings.controls || 'auto'
  if (c === 'off') return false
  if (c === 'on') return true
  return !(input.sawKeyboard && !input.sawTouch)
}

// --- the rules ---

function fits(p: number, r: number, cx: number, cy: number): boolean {
  const at = (p * 4 + r) * 4
  for (let k = 0; k < 4; k++) {
    const xx = cx + CELL_X[at + k]
    const yy = cy + CELL_Y[at + k]
    if (xx < 0 || xx >= W || yy >= H) return false
    if (yy >= 0 && board[yy * W + xx]) return false
  }
  return true
}

/** The next shape: the seven in a shuffled bag, a new bag when it is empty. */
function draw(): number {
  if (!bag) {
    let order = '0123456'
    bag = ''
    while (order) {
      const i = rand(order.length)
      bag += order[i]
      order = order.slice(0, i) + order.slice(i + 1)
    }
  }
  const p = bag.charCodeAt(0) - 48
  bag = bag.slice(1)
  return p
}

/** The next piece at the top. False when it does not fit: the game is over. */
function spawn(p: number): boolean {
  piece = p
  rot = 0
  x = p === 1 ? 4 : 3
  y = 1
  fallAcc = 0
  lockSteps = 0
  lockMoves = 0
  dirty = true
  return fits(piece, rot, x, y)
}

function nextPiece(): boolean {
  const p = queue.shift()!
  while (queue.length < 3) queue.push(draw())
  panelDirty = true
  holdUsed = false
  return spawn(p)
}

function move(dx: number): boolean {
  if (!fits(piece, rot, x + dx, y)) return false
  x += dx
  moved()
  return true
}

function turn(dir: number): boolean {
  const r = (rot + dir + 4) & 3
  for (let k = 0; k < KICK_X.length; k++) {
    const kx = KICK_X[k] * (dir < 0 ? -1 : 1)
    if (fits(piece, r, x + kx, y + KICK_Y[k])) {
      rot = r
      x += kx
      y += KICK_Y[k]
      moved()
      return true
    }
  }
  return false
}

/** A move or a turn on the ground gives the piece a little longer before it locks (fifteen times). */
function moved() {
  dirty = true
  if (lockMoves < 15 && !fits(piece, rot, x, y + 1)) {
    lockSteps = 0
    lockMoves++
  }
}

function keep() {
  if (!holdOn || holdUsed) return
  const was = holdPiece
  holdPiece = piece
  holdUsed = true
  panelDirty = true
  if (was < 0) {
    const p = queue.shift()!
    while (queue.length < 3) queue.push(draw())
    spawn(p)
  } else {
    spawn(was)
  }
  holdUsed = true
}

function ghostY(): number {
  let gy = y
  while (fits(piece, rot, x, gy + 1)) gy++
  return gy
}

/** Puts the piece into the well. Returns the full rows, as bits; -1 when it locked above the top. */
function lock(): number {
  const at = (piece * 4 + rot) * 4
  let visible = false
  for (let k = 0; k < 4; k++) {
    const yy = y + CELL_Y[at + k]
    if (yy >= 0) board[yy * W + x + CELL_X[at + k]] = piece + 1
    if (yy >= TOP) visible = true
  }
  dirty = true
  if (!visible) return -1
  let full = 0
  for (let row = 0; row < H; row++) {
    let n = 0
    for (let col = 0; col < W; col++) if (board[row * W + col]) n++
    if (n === W) full |= 1 << row
  }
  return full
}

const LINE_SCORES = [0, 100, 300, 500, 800]

function clearRows(full: number) {
  let n = 0
  for (let row = 0; row < H; row++) {
    if (!(full & (1 << row))) continue
    n++
    board.copyWithin(W, 0, row * W)
    board.fill(0, 0, W)
  }
  score += LINE_SCORES[n] * level
  lines += n
  level = Math.max(level, startLevel + Math.floor(lines / 10))
  dirty = true
}

function gravity(): number {
  return GRAVITY[Math.min(GRAVITY.length - 1, level - 1)] - (level > GRAVITY.length ? 1 : 0)
}

// --- drawing ---

function placeWell() {
  const p = L.play
  const ts = L.ts
  b = Math.max(2, Math.floor((p.h - 2) / (H - TOP)))
  for (; b > 2; b--) {
    mb = Math.max(2, Math.round(b * 0.6))
    panelW = Math.max(textWidth('NEXT', ts), 4 * mb) + 2 * ts + 2
    if (W * b + 2 + panelW + 3 <= p.w) break
  }
  mb = Math.max(2, Math.round(b * 0.6))
  panelW = Math.max(textWidth('NEXT', ts), 4 * mb) + 2 * ts + 2
  const total = W * b + 2 + 2 + panelW
  wx = p.x + ((p.w - total) >> 1) + 1
  wy = p.y + ((p.h - (H - TOP) * b) >> 1)
  px = wx + W * b + 3
}

function drawWellFrame() {
  const c = cells!
  const cols = L.cols
  const rows = L.rows
  const p = L.play
  rect(c, cols, rows, p.x, p.y, p.w, p.h, UI.BG)
  rect(c, cols, rows, wx - 1, wy - 1, W * b + 2, (H - TOP) * b + 2, WELL_EDGE)
  rect(c, cols, rows, wx - 1, wy - 1, W * b + 2, 1, WELL_EDGE_HI)
  rect(c, cols, rows, wx - 1, wy - 1, 1, (H - TOP) * b + 2, WELL_EDGE_HI)
  shown.fill(-1)
  dirty = true
  panelDirty = true
}

/** One cell of the well: empty, a shape's color (1-7), its ghost (8-14), or flashing (15). */
function drawCell(col: number, row: number, code: number) {
  const c = cells!
  const cols = L.cols
  const rows = L.rows
  const cx = wx + col * b
  const cy = wy + row * b
  if (code === 0) {
    rect(c, cols, rows, cx, cy, b, b, WELL_BG)
    if (b >= 4) c[cy * cols + cx] = WELL_DOT
  } else if (code <= 7) {
    block(c, cx, cy, b, BLOCK + (code - 1) * 3)
  } else if (code <= 14) {
    rect(c, cols, rows, cx, cy, b, b, GHOST)
    if (b >= 3) rect(c, cols, rows, cx + 1, cy + 1, b - 2, b - 2, WELL_BG)
  } else {
    rect(c, cols, rows, cx, cy, b, b, FLASH)
  }
}

/** A block with a light top and left and a dark bottom and right. */
function block(c: Uint8Array, cx: number, cy: number, size: number, ink: number) {
  const cols = L.cols
  const rows = L.rows
  rect(c, cols, rows, cx, cy, size, size, ink + 2)
  rect(c, cols, rows, cx, cy, size - 1, size - 1, ink + 1)
  if (size >= 3) rect(c, cols, rows, cx + 1, cy + 1, size - 2, size - 2, ink)
}

/** What the well should show now, compared with what it shows: only the cells that differ are drawn. */
function drawWell() {
  for (let row = TOP; row < H; row++) {
    const flashing = (clearing >> row) & 1
    for (let col = 0; col < W; col++) want[(row - TOP) * W + col] = flashing ? 15 : board[row * W + col]
  }
  if (mode === 'play' || mode === 'pause') {
    const at = (piece * 4 + rot) * 4
    if (ghostOn) {
      const gy = ghostY()
      for (let k = 0; k < 4; k++) {
        const row = gy + CELL_Y[at + k] - TOP
        if (row >= 0) want[row * W + x + CELL_X[at + k]] = piece + 8
      }
    }
    for (let k = 0; k < 4; k++) {
      const row = y + CELL_Y[at + k] - TOP
      if (row >= 0) want[row * W + x + CELL_X[at + k]] = piece + 1
    }
  }
  for (let i = 0; i < W * (H - TOP); i++) {
    if (want[i] !== shown[i]) {
      shown[i] = want[i]
      drawCell(i % W, (i / W) | 0, want[i])
    }
  }
}

/** A shape in its first turn, small, centered in a box 4 x 2 of size `size` at (bx, by). */
function mini(p: number, bx: number, by: number, size: number) {
  const at = p * 16
  let minX = 9
  let maxX = 0
  let minY = 9
  let maxY = 0
  for (let k = 0; k < 4; k++) {
    minX = Math.min(minX, CELL_X[at + k])
    maxX = Math.max(maxX, CELL_X[at + k])
    minY = Math.min(minY, CELL_Y[at + k])
    maxY = Math.max(maxY, CELL_Y[at + k])
  }
  const ox = bx + ((4 * size - (maxX - minX + 1) * size) >> 1)
  const oy = by + ((2 * size - (maxY - minY + 1) * size) >> 1)
  for (let k = 0; k < 4; k++) {
    block(cells!, ox + (CELL_X[at + k] - minX) * size, oy + (CELL_Y[at + k] - minY) * size, size, BLOCK + p * 3)
  }
}

function drawPanel() {
  const c = cells!
  const cols = L.cols
  const rows = L.rows
  const ts = L.ts
  const p = L.play
  rect(c, cols, rows, px, p.y, panelW, p.h, UI.BG)
  let top = wy
  const inner = px + ts + 1
  drawText(c, cols, rows, 'NEXT', inner, top, ts, PANEL_INK)
  top += 5 * ts + 2 * ts
  for (let i = 0; i < previews && i < queue.length; i++) {
    if (mode !== 'title') mini(queue[i], inner, top, i === 0 ? mb : Math.max(2, mb - 1))
    top += 3 * mb
  }
  if (holdOn) {
    top += ts
    drawText(c, cols, rows, 'KEEP', inner, top, ts, PANEL_INK)
    top += 5 * ts + 2 * ts
    rect(c, cols, rows, inner - 1, top - 1, 4 * mb + 2, 2 * mb + 2, holdUsed ? UI.HUD_DIM : WELL_EDGE)
    rect(c, cols, rows, inner, top, 4 * mb, 2 * mb, WELL_BG)
    if (holdPiece >= 0) mini(holdPiece, inner, top, mb)
  }
  panelDirty = false
}

let hudScore = -1
let hudLines = -1
let hudLevel = -1

function drawHud(force: boolean) {
  const c = cells!
  if (force) {
    drawHudBar(c)
    hudScore = hudLines = hudLevel = -1
    hudSlots('SCORE 00000', 'LINES 000', 'LVL 00')
  }
  if (score !== hudScore) {
    hudScore = score
    hudField(c, HUD.lx, HUD.lw, 'SCORE', String(score))
  }
  if (lines !== hudLines) {
    hudLines = lines
    hudField(c, HUD.mx, HUD.mw, 'LINES', String(lines))
  }
  if (level !== hudLevel) {
    hudLevel = level
    hudField(c, HUD.rx, HUD.rw, 'LVL', String(level), true)
  }
}

function animatePalette(now: number) {
  if (high) {
    palette[FLASH] = (modeSteps >> 2) & 1 ? 0x000000 : 0xffffff
    return
  }
  palette[FLASH] = (modeSteps >> 2) & 1 ? 0xffffff : 0xb57cf5
  palette[UI.CARD_BLINK] = (now / 500) & 1 ? COLORS[UI.CARD_INK] : COLORS[UI.CARD_DIM]
  palette[UI.CARD_HI] = mix(0xffd43b, 0xff6b9e, (now / 2) & 255)
  // The well's edge glows with the level's color after a clear.
  palette[WELL_EDGE] = mix(COLORS[WELL_EDGE], PIECE_COLORS[(level - 1) % 7], mode === 'clear' ? 200 : 60)
}

// --- cards ---

function card() {
  const lines: any[] = []
  if (mode === 'title') {
    lines.push({ text: 'BLOCK', scale: 3, ink: UI.CARD_TITLE })
    lines.push({ text: 'DROP', scale: 3, ink: UI.CARD_TITLE })
    lines.push({ text: fast ? 'FILL A ROW TO CLEAR IT' : 'A SLOW PUZZLE: DOWN LOWERS A ROW', ink: UI.CARD_DIM, optional: true })
    lines.push({ text: '', gap: 3 })
    lines.push(...scoreLines(scores, -1))
    lines.push({ text: '', gap: 3, optional: true })
    lines.push({ text: fast ? 'TAP OR PRESS A TO START' : 'PRESS TO START', ink: UI.CARD_BLINK })
    if (fast) lines.push({ text: 'UP TURNS  SPACE DROPS', ink: UI.CARD_DIM, optional: true })
  } else if (mode === 'pause') {
    lines.push({ text: 'PAUSED', scale: 2, ink: UI.CARD_TITLE })
    lines.push({ text: '', gap: 2 })
    lines.push({ text: 'GO ON', key: 1 })
    lines.push({ text: 'NEW GAME', key: 2 })
  } else if (mode === 'over') {
    lines.push({ text: 'GAME', scale: 3, ink: UI.CARD_TITLE })
    lines.push({ text: 'OVER', scale: 3, ink: UI.CARD_TITLE })
    lines.push({ text: 'SCORE ' + score, scale: 2, ink: UI.CARD_INK })
    if (rank >= 0) lines.push({ text: rank === 0 ? 'NEW HIGH SCORE!' : 'A HIGH SCORE!', ink: UI.CARD_HI })
    lines.push({ text: '', gap: 2, optional: true })
    lines.push(...scoreLines(scores, rank))
    lines.push({ text: '', gap: 2, optional: true })
    lines.push({ text: fast ? 'TAP TO PLAY AGAIN' : 'PRESS TO PLAY AGAIN', ink: UI.CARD_BLINK })
  }
  if (lines.length) drawCard(cells!, lines, false)
}

// --- keeping the game ---

function snapshot(): any {
  let cellsText = ''
  for (let i = 0; i < board.length; i++) cellsText += String.fromCharCode(48 + board[i])
  return { board: cellsText, piece, rot, x, y, queue: queue.slice(), bag, holdPiece, holdUsed, score, lines, level, startLevel, seed: getSeed(), over: mode === 'over' }
}

function restoreGame(s: any): boolean {
  if (!s || typeof s !== 'object' || typeof s.board !== 'string' || s.board.length !== board.length) return false
  for (let i = 0; i < board.length; i++) board[i] = s.board.charCodeAt(i) - 48
  piece = s.piece | 0
  rot = s.rot & 3
  x = s.x | 0
  y = s.y | 0
  queue.length = 0
  for (const q of s.queue || []) queue.push(q | 0)
  while (queue.length < 3) queue.push(draw())
  bag = String(s.bag || '')
  holdPiece = s.holdPiece ?? -1
  holdUsed = !!s.holdUsed
  score = s.score | 0
  lines = s.lines | 0
  level = s.level || 1
  startLevel = s.startLevel || 1
  setSeed(s.seed | 0)
  dirty = panelDirty = true
  return true
}

function remember() {
  frameos.remember('game', mode === 'play' || mode === 'pause' || mode === 'clear' ? snapshot() : null)
}

// --- the frame ---

function newScreen(app: any) {
  const pixelSize = Number(settings.pixelSize) || 0
  const right = holdOn ? [{ bit: A, glyph: 'rotr' }, { bit: C, glyph: 'hold' }] : [{ bit: B, glyph: 'rotl' }, { bit: A, glyph: 'rotr' }]
  layout(width, height, pixelSize, {
    left: { items: [{ bit: LEFT, glyph: 'left' }, { bit: RIGHT, glyph: 'right' }, { bit: UP, glyph: 'drop' }, { bit: DOWN, glyph: 'down' }], cross: true },
    right: { items: right },
    pauseBit: PAUSE,
    name: 'BLOCK DROP',
  }, controlsOn())
  cells = new Uint8Array(L.cols * L.rows)
  scores = readScores(app.state.scores)
  placeWell()
  redraw = true
}

function startGame() {
  board.fill(0)
  score = 0
  lines = 0
  startLevel = Math.max(1, Number(settings.startLevel) || 1)
  level = startLevel
  holdPiece = -1
  holdUsed = false
  gameSeed = (Date.now() ^ (Math.random() * 0x7fffffff)) | 0
  setSeed(gameSeed)
  bag = ''
  queue.length = 0
  while (queue.length < 3) queue.push(draw())
  clearing = 0
  pending = 0
  mode = 'play'
  modeSteps = 0
  nextPiece()
  redraw = true
  releaseAll()
}

function endGame(app: any) {
  scores = readScores(app.state.scores)
  rank = placeScore(scores, score)
  if (rank >= 0) frameos.setState('scores', scores)
  mode = 'over'
  modeSteps = 0
  redraw = true
  frameos.remember('game', null)
  if (!fast) frameos.setState('game', null)
}

/** After a piece came to rest: rows to clear (flashing first, where frames are fast), then the next. */
function afterLock(app: any, full: number) {
  if (full < 0) {
    endGame(app)
    return
  }
  if (full && fast) {
    clearing = full
    mode = 'clear'
    modeSteps = 0
    return
  }
  if (full) clearRows(full)
  if (!nextPiece()) endGame(app)
}

function ensure(app: any, context: any, now: number) {
  const fresh = !cells
  if (!env(app, context, now, fresh) && !fresh) return
  const key = [width, height, settings.pixelSize, controlsOn(), high, holdOn, previews].join(':')
  if (key === screenKey || !(fresh || mode !== 'play')) return
  screenKey = key
  newScreen(app)
  fillPalette(palette, COLORS, DARK, high)
  if (fresh) {
    setSeed(Date.now() | 0)
    while (queue.length < 3) queue.push(draw())
    const kept = fast ? frameos.recall('game') : app.state.game
    if (kept && restoreGame(kept) && !kept.over) mode = fast ? 'pause' : 'play'
    else mode = 'title'
  }
  idleSince = now
  restartClock(now)
}

export function get(app: any, context: any) {
  const now = Date.now()
  ensure(app, context, now)
  const c = cells!
  if (fast) play(app, now)
  if (redraw) {
    redraw = false
    rect(c, L.cols, L.rows, 0, 0, L.cols, L.rows, UI.BAR)
    drawWellFrame()
    drawWell()
    drawPanel()
    drawHud(true)
    drawControls(c, fast ? held() : 0)
    if (mode !== 'play' && mode !== 'clear') card()
  } else {
    if (dirty) {
      dirty = false
      drawWell()
    }
    if (panelDirty) drawPanel()
    drawHud(false)
    updateControls(c, held())
  }
  animatePalette(now)
  if (!fast) {
    frameos.setNextSleep(3600)
  } else if (mode === 'title' || mode === 'pause' || mode === 'over') {
    frameos.setNextSleep(now - idleSince < 60000 ? 0.5 : 3600)
  } else {
    idleSince = now
  }
  return frameos.pixels(c, palette, { width: L.cols, height: L.rows, pixelSize: L.px })
}

function play(app: any, now: number) {
  const pressed = consume()
  const touched = input.touchStarted
  input.touchStarted = false
  const tx = input.touchX
  const ty = input.touchY
  if (mode === 'play' || mode === 'clear') {
    if (pressed & PAUSE || (touched && ty < L.hud.y + L.hud.h)) {
      mode = 'pause'
      redraw = true
      remember()
      return
    }
  } else if (mode === 'pause') {
    const k = touched ? cardKeyAt(tx, ty) : 0
    if (k === 2 || pressed & B) startGame()
    else if (k === 1 || (touched && !k) || pressed & (A | PAUSE | UP)) {
      mode = 'play'
      redraw = true
      restartClock(now)
    }
    return
  } else if (mode === 'title' || (mode === 'over' && modeSteps > 40)) {
    if (touched || pressed & (A | PAUSE | UP)) startGame()
    return
  }
  const heldBits = held()
  const steps = stepsDue(now)
  pending |= pressed
  let first = true
  for (let s = 0; s < steps; s++) {
    modeSteps++
    if (mode === 'clear') {
      dirty = true // the flashing rows
      if (modeSteps >= 20) {
        clearRows(clearing)
        clearing = 0
        mode = 'play'
        panelDirty = true
        if (!nextPiece()) {
          endGame(app)
          return
        }
      }
      continue
    }
    if (mode !== 'play') return
    const p = first ? pending : 0
    if (first) pending = 0
    first = false
    // Sideways: once on the press, then again and again while held.
    if (p & LEFT) { move(-1); dasLeft = 0 }
    else if (heldBits & LEFT) { if (++dasLeft >= 10 && (dasLeft - 10) % 2 === 0) move(-1) }
    if (p & RIGHT) { move(1); dasRight = 0 }
    else if (heldBits & RIGHT) { if (++dasRight >= 10 && (dasRight - 10) % 2 === 0) move(1) }
    if (p & A) turn(1)
    if (p & B) turn(-1)
    if (p & C) keep()
    if (p & UP) {
      const gy = ghostY()
      score += 2 * (gy - y)
      y = gy
      afterLock(app, lock())
      continue
    }
    // Falling: faster while Down is held.
    const soft = (heldBits & DOWN) !== 0
    const every = soft ? Math.min(2, gravity()) : gravity()
    if (++fallAcc >= every) {
      fallAcc = 0
      if (fits(piece, rot, x, y + 1)) {
        y++
        if (soft) score++
        dirty = true
        lockSteps = 0
      }
    }
    if (!fits(piece, rot, x, y + 1)) {
      if (++lockSteps >= 30) afterLock(app, lock())
    }
  }
  if (mode === 'play' && now - snapAt > 1000) {
    snapAt = now
    remember()
  }
}

/** E-paper: one press, one move. Nothing falls by itself. */
function slowStep(app: any, bits: number) {
  if (mode === 'title' || mode === 'over') {
    startGame()
    frameos.setState('game', snapshot())
    return
  }
  if (bits & PAUSE) return
  if (bits & LEFT) move(-1)
  if (bits & RIGHT) move(1)
  if (bits & A) turn(1)
  if (bits & B) turn(-1)
  if (bits & C) keep()
  if (bits & UP) {
    y = ghostY()
    afterLock(app, lock())
  } else if (bits & DOWN) {
    if (fits(piece, rot, x, y + 1)) y++
    else afterLock(app, lock())
  }
  if (mode === 'play') frameos.setState('game', snapshot())
  redraw = true
}

export function onEvent(app: any, context: any) {
  const event = context.event
  const payload = context.payload || {}
  if (event === 'close') {
    if (fast && (mode === 'play' || mode === 'clear')) {
      mode = 'pause'
      redraw = true
      remember()
    }
    releaseAll()
    return false
  }
  if (event === 'open') return true
  if (event === 'back' || event === 'forward') {
    if (!fast) return false
    if ((mode === 'play' || mode === 'clear') && event === 'back') {
      mode = 'pause'
      redraw = true
      remember()
      return true
    }
    if (mode === 'pause' && event === 'forward') input.pressed |= A
    return true
  }
  ensure(app, null, Date.now())
  const kind = takeEvent(event, payload)
  if (!kind) return false
  if (!fast) {
    // E-paper. Buttons act when they are let go, so two pressed together (LEFT and RIGHT) can turn the
    // piece; a double press of Down drops it. A tap or a key acts at once.
    let bits = consume()
    if (event === 'gpio') {
      bits = 0
      if (payload.action === 'up' && input.combo) {
        const combo = input.combo
        input.combo = 0
        bits = (combo & LEFT) && (combo & RIGHT) ? A : combo
      }
    } else if (event === 'button') {
      const doubled = input.doubled
      input.doubled = 0
      // A double press of Down drops.
      bits = doubled & DOWN ? UP : 0
    }
    if (input.touchStarted) {
      input.touchStarted = false
      if (mode === 'title' || mode === 'over') bits |= A
    }
    if (!bits) return false
    slowStep(app, bits)
    return true
  }
  if (mode === 'play' || mode === 'clear') return event === 'pointerDown' || event === 'keyDown' || event === 'gpio'
  return event === 'pointerDown' || event === 'keyDown' || event === 'gpio' || event === 'button'
}

sources.pieces.ts:
// The seven four-cell shapes and their four turns, worked out once from
// their first turn: each turn is the last one rotated a quarter clockwise in
// its box (n x n). CELL_X / CELL_Y hold the four cells of shape p, turn r at
// (p * 4 + r) * 4.
const SHAPES = [
  // n, then n rows
  '4|....|####|....|....', // I
  '2|##|##', // O
  '3|.#.|###|...', // T
  '3|.##|##.|...', // S
  '3|##.|.##|...', // Z
  '3|#..|###|...', // J
  '3|..#|###|...', // L
]
export const CELL_X = new Int8Array(7 * 4 * 4)
export const CELL_Y = new Int8Array(7 * 4 * 4)

for (let p = 0; p < 7; p++) {
  const parts = SHAPES[p].split('|')
  const n = Number(parts[0])
  // The first turn's cells.
  let xs: number[] = []
  let ys: number[] = []
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (parts[1 + y][x] === '#') { xs.push(x); ys.push(y) }
  for (let r = 0; r < 4; r++) {
    for (let k = 0; k < 4; k++) {
      CELL_X[(p * 4 + r) * 4 + k] = xs[k]
      CELL_Y[(p * 4 + r) * 4 + k] = ys[k]
    }
    // A quarter turn clockwise: (x, y) -> (n - 1 - y, x).
    const nx: number[] = []
    const ny: number[] = []
    for (let k = 0; k < 4; k++) {
      nx.push(n - 1 - ys[k])
      ny.push(xs[k])
    }
    xs = nx
    ys = ny
  }
}

// Where a turn may push the piece when it does not fit where it is: in
// place first, then a cell aside, up, two aside (the long piece needs them).
export const KICK_X = [0, -1, 1, 0, -1, 1, -2, 2]
export const KICK_Y = [0, 0, 0, -1, -1, -1, 0, 0]

// Steps of 1/60 s per row the piece falls, by level.
export const GRAVITY = [48, 43, 38, 33, 28, 23, 18, 13, 8, 6, 5, 5, 5, 4, 4, 4, 3, 3, 3, 2]

sources.font.ts:
// A 3x5 pixel font for text drawn into the cells. Each glyph is five digits,
// one per row from the top, each row three bits (4 = left, 2 = middle,
// 1 = right): "25755" is
//   .#.
//   #.#
//   ###
//   #.#
//   #.#
// Text is drawn only when it changes, never every frame.
const CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,:!?-+/'()<>=#%*"
const DATA =
  '25755656563444365556746477464434553557557222711152556554444757755655552555265644' +
  '25563656553421672222555575555255775552555522271247755572622761247612165571174616' +
  '34757711227575775716' +
  '00000000020002402020222026120200700027201124422000244424222412421421240707057575' +
  '5124505250'

// Where each character's five digits start in DATA, by char code (-1: none).
const AT = new Int16Array(128).fill(-1)
for (let i = 0; i < CHARS.length; i++) AT[CHARS.charCodeAt(i)] = i * 5

/** Cells a line of text takes at `scale`: 4 a letter (3 and a gap), less the last gap. */
export function textWidth(text: string, scale: number): number {
  return text.length ? (text.length * 4 - 1) * scale : 0
}

/** One line of text into `cells` (a grid `cols` x `rows`) at (x, y), each dot a `scale` square of `value`.
 *  Lower case is drawn as upper case; unknown characters as spaces. */
export function drawText(cells: Uint8Array, cols: number, rows: number, text: string, x: number, y: number,
    scale: number, value: number) {
  for (let g = 0; g < text.length; g++) {
    let code = text.charCodeAt(g)
    if (code >= 97 && code <= 122) code -= 32
    const at = code < 128 ? AT[code] : -1
    if (at < 0) continue
    const left = x + g * 4 * scale
    for (let row = 0; row < 5; row++) {
      const bits = DATA.charCodeAt(at + row) - 48
      if (!bits) continue
      const top = y + row * scale
      for (let col = 0; col < 3; col++) {
        if (!(bits & (4 >> col))) continue
        const x0 = left + col * scale
        for (let dy = 0; dy < scale; dy++) {
          const yy = top + dy
          if (yy < 0 || yy >= rows) continue
          const from = x0 < 0 ? 0 : x0
          const to = x0 + scale > cols ? cols : x0 + scale
          if (to > from) cells.fill(value, yy * cols + from, yy * cols + to)
        }
      }
    }
  }
}

/** Text centered on `cx`. */
export function drawTextCentered(cells: Uint8Array, cols: number, rows: number, text: string, cx: number, y: number,
    scale: number, value: number) {
  drawText(cells, cols, rows, text, cx - (textWidth(text, scale) >> 1), y, scale, value)
}

/** Text with a drop shadow one dot down and right: the titles. */
export function drawTextShadow(cells: Uint8Array, cols: number, rows: number, text: string, x: number, y: number,
    scale: number, value: number, shadow: number) {
  const offset = scale > 1 ? scale >> 1 : 1
  drawText(cells, cols, rows, text, x + offset, y + offset, scale, shadow)
  drawText(cells, cols, rows, text, x, y, scale, value)
}

sources.gfx.ts:
// Drawing into the cells: one byte a cell, an index into the game's palette.
// Every function clips to the grid. Rows are filled with typed-array fill
// (native) and nothing allocates, so they are cheap enough per frame for
// the small things that move.

/** A filled rectangle. */
export function rect(cells: Uint8Array, cols: number, rows: number, x: number, y: number, w: number, h: number,
    value: number) {
  let x0 = x | 0
  let y0 = y | 0
  let x1 = x0 + (w | 0)
  let y1 = y0 + (h | 0)
  if (x0 < 0) x0 = 0
  if (y0 < 0) y0 = 0
  if (x1 > cols) x1 = cols
  if (y1 > rows) y1 = rows
  if (x1 <= x0) return
  for (let yy = y0; yy < y1; yy++) cells.fill(value, yy * cols + x0, yy * cols + x1)
}

/** A rectangle's outline, `t` cells thick. */
export function frame(cells: Uint8Array, cols: number, rows: number, x: number, y: number, w: number, h: number,
    value: number, t: number) {
  rect(cells, cols, rows, x, y, w, t, value)
  rect(cells, cols, rows, x, y + h - t, w, t, value)
  rect(cells, cols, rows, x, y + t, t, h - 2 * t, value)
  rect(cells, cols, rows, x + w - t, y + t, t, h - 2 * t, value)
}

/** A filled rectangle with its corners cut by `r` cells (1 or 2 looks round at these sizes). */
export function roundRect(cells: Uint8Array, cols: number, rows: number, x: number, y: number, w: number,
    h: number, value: number, r: number) {
  for (let i = 0; i < r; i++) {
    const cut = r - i
    rect(cells, cols, rows, x + cut, y + i, w - 2 * cut, 1, value)
    rect(cells, cols, rows, x + cut, y + h - 1 - i, w - 2 * cut, 1, value)
  }
  rect(cells, cols, rows, x, y + r, w, h - 2 * r, value)
}

/** Copies a rectangle of `from` into `to` (two grids of the same size): erases what moved by putting the
 *  background back. */
export function restore(to: Uint8Array, from: Uint8Array, cols: number, rows: number, x: number, y: number,
    w: number, h: number) {
  let x0 = x | 0
  let y0 = y | 0
  let x1 = x0 + (w | 0)
  let y1 = y0 + (h | 0)
  if (x0 < 0) x0 = 0
  if (y0 < 0) y0 = 0
  if (x1 > cols) x1 = cols
  if (y1 > rows) y1 = rows
  for (let yy = y0; yy < y1; yy++) {
    const row = yy * cols
    for (let xx = x0; xx < x1; xx++) to[row + xx] = from[row + xx]
  }
}

/** A line from (x0, y0) to (x1, y1), every cell on it, by Bresenham's integer steps. */
export function line(cells: Uint8Array, cols: number, rows: number, x0: number, y0: number, x1: number, y1: number,
    value: number) {
  x0 |= 0
  y0 |= 0
  x1 |= 0
  y1 |= 0
  const dx = x1 > x0 ? x1 - x0 : x0 - x1
  const dy = y1 > y0 ? y0 - y1 : y1 - y0
  const sx = x0 < x1 ? 1 : -1
  const sy = y0 < y1 ? 1 : -1
  let err = dx + dy
  for (;;) {
    if (x0 >= 0 && y0 >= 0 && x0 < cols && y0 < rows) cells[y0 * cols + x0] = value
    if (x0 === x1 && y0 === y1) return
    const e2 = 2 * err
    if (e2 >= dy) {
      err += dy
      x0 += sx
    }
    if (e2 <= dx) {
      err += dx
      y0 += sy
    }
  }
}

/** A sprite: `w` x `h` bytes from `data` at `offset`, 0 transparent, any other byte a palette index. */
export function sprite(cells: Uint8Array, cols: number, rows: number, data: Uint8Array, offset: number, w: number,
    h: number, x: number, y: number) {
  x |= 0
  y |= 0
  for (let j = 0; j < h; j++) {
    const yy = y + j
    if (yy < 0 || yy >= rows) continue
    const row = yy * cols
    const src = offset + j * w
    for (let i = 0; i < w; i++) {
      const v = data[src + i]
      const xx = x + i
      if (v && xx >= 0 && xx < cols) cells[row + xx] = v
    }
  }
}

/** A sprite from rows of text ('.' transparent, any other character a palette index through `inks`, a
 *  string of the same length as `keys`: "#" -> inks[0]...). For pictures built once, not per frame. */
export function spriteFrom(rowsText: string[], keys: string, inks: number[]): Uint8Array {
  const h = rowsText.length
  const w = rowsText[0].length
  const out = new Uint8Array(w * h)
  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) {
      const k = keys.indexOf(rowsText[j][i])
      if (k >= 0) out[j * w + i] = inks[k]
    }
  }
  return out
}

sources.palette.ts:
// The palette: indices 0-23 are the family's (the bars, the buttons, the
// HUD, the cards over the play area), the rest each game's own. A game gives
// every index a color and says which are dark in high contrast, where the
// same cells are drawn with two colors: black on white.
export const UI = {
  BG: 0, // the play area's background
  BAR: 1, // behind the controls
  SEP: 2, // the line between the controls and the play area
  HUD_BG: 3,
  HUD_INK: 4,
  HUD_DIM: 5,
  BTN_EDGE: 6,
  BTN: 7,
  BTN_ON: 8,
  BTN_INK: 9,
  BTN_INK_ON: 10,
  CARD: 11, // the title, pause and game-over cards
  CARD_EDGE: 12,
  CARD_INK: 13,
  CARD_TITLE: 14,
  CARD_DIM: 15,
  CARD_BLINK: 16, // "tap to start": blinks by its color
  CARD_SHADOW: 17,
  CARD_HI: 18, // a new high score: cycles
  CARD_KEY: 19, // a button on a card
  CARD_KEY_INK: 20,
}
export const GAME = 24 // the first index of the game's own

/** The family's colors, in the order of UI's indices, for a game with the accent `accent`. */
export function familyColors(bg: number, accent: number, title: number): number[] {
  return [
    bg, // BG
    0x10141f, // BAR
    0x2a3346, // SEP
    0x10141f, // HUD_BG
    0xe8ecf4, // HUD_INK
    0x8590a6, // HUD_DIM
    0x05070c, // BTN_EDGE
    0x2b3448, // BTN
    accent, // BTN_ON
    0xc9d2e3, // BTN_INK
    0x10141f, // BTN_INK_ON
    0x141a29, // CARD
    accent, // CARD_EDGE
    0xe8ecf4, // CARD_INK
    title, // CARD_TITLE
    0x8590a6, // CARD_DIM
    0xffffff, // CARD_BLINK
    0x05070c, // CARD_SHADOW
    0xffd34d, // CARD_HI
    accent, // CARD_KEY
    0x10141f, // CARD_KEY_INK
    0, 0, 0,
  ]
}

/** Which of the family's indices are black in high contrast (1) or white (0). */
export const FAMILY_DARK = [0, 0, 1, 0, 1, 1, 1, 0, 1, 1, 0, 0, 1, 1, 1, 1, 1, 0, 1, 1, 0, 0, 0, 0]

/** Fills `palette` (256 entries) with the color table, or black and white where `high`. */
export function fillPalette(palette: Uint32Array, colors: number[], dark: number[], high: boolean) {
  for (let i = 0; i < 256; i++) {
    if (high) palette[i] = dark[i] ? 0x000000 : 0xffffff
    else palette[i] = i < colors.length ? colors[i] : 0
  }
}

/** A color between a and b, t from 0 to 256. */
export function mix(a: number, b: number, t: number): number {
  const r = ((a >> 16) & 255) + ((((b >> 16) & 255) - ((a >> 16) & 255)) * t >> 8)
  const g = ((a >> 8) & 255) + ((((b >> 8) & 255) - ((a >> 8) & 255)) * t >> 8)
  const bl = (a & 255) + (((b & 255) - (a & 255)) * t >> 8)
  return (r << 16) | (g << 8) | bl
}

sources.layout.ts:
// Where everything goes, in cells: the cell size, the HUD strip along the
// top, the play area, and the on-screen controls — a bar along the bottom on
// a tall or square screen, a column each side on a wide one — plus the
// pause button. Also the controls' drawing and their hit-testing.
import { rect, roundRect } from './gfx'
import { drawText, textWidth } from './font'
import { UI } from './palette'

// The buttons' pictures: 8x8, '#' drawn. Triangles for the D-pad, so a press
// reads at a glance.
const GLYPHS: Record<string, string> = {
  left: '.....#......##.....###....####....####.....###......##.......#..',
  right: '..#.......##......###.....####....####....###.....##......#.....',
  up: '...................##.....####...######.########................',
  down: '................########.######...####.....##...................',
  pause: '.........##..##..##..##..##..##..##..##..##..##..##..##.........',
  rotr: '..####.#.#....###....####.......#.......#......#.#....#...####..',
  rotl: '#.####..##....#.###....#.......#.......##......#.#....#...####..',
  drop: '...##......##......##....######...####.....##...........########',
  hold: '#########......##.####.##.#..#.##.#..#.##.####.##......#########',
  boost: '...##.....####...##..##.##....##...##.....####...##..##.##....##',
}

export type Button = { bit: number; glyph: string; x: number; y: number; w: number; h: number }
export type Group = { items: { bit: number; glyph: string }[]; cross?: boolean }
export type Spec = { left: Group; right: Group; pauseBit: number; name?: string }

/** The current layout. Rectangles are cells: x, y, w, h. */
export const L = {
  px: 4, // pixels a cell
  cols: 0,
  rows: 0,
  ts: 1, // the text scale: dots of the font a cell
  side: false, // controls in columns at the sides
  controls: true,
  name: '', // the game's, at the top of the left column
  hud: { x: 0, y: 0, w: 0, h: 0 },
  play: { x: 0, y: 0, w: 0, h: 0 },
  buttons: [] as Button[],
}

const DIRS = 1 | 2 | 4 | 8 // left, right, up, down: a finger slides between these

/** Works the layout out for a `width` x `height` image. `pixelSize` 0 picks: about 120 cells across the
 *  short side (4 px a cell on a 480 px screen). */
export function layout(width: number, height: number, pixelSize: number, spec: Spec, controls: boolean) {
  const short = width < height ? width : height
  const px = pixelSize > 0 ? pixelSize : Math.max(2, Math.round(short / 120))
  const cols = Math.floor(width / px)
  const rows = Math.floor(height / px)
  L.px = px
  L.cols = cols
  L.rows = rows
  L.ts = Math.max(1, Math.round(short / (120 * px)))
  L.controls = controls
  L.name = spec.name || ''
  const hudH = 5 * L.ts + 4
  const m = Math.ceil(24 / px) // a swipe from within 24 px of an edge is the frame's
  let b = Math.round(Math.min(150, Math.max(56, short * 0.13)) / px) // a button, at least 56 px
  const g = Math.max(1, Math.round(b / 8))
  const buttons: Button[] = []
  const pauseSize = Math.max(Math.ceil(44 / px), Math.round(b * 0.75))
  L.side = controls && width >= height * 1.25
  if (!controls) {
    L.hud = { x: 0, y: 0, w: cols, h: hudH }
    L.play = { x: 0, y: hudH, w: cols, h: rows - hudH }
  } else if (L.side) {
    // A column each side, the play area between them.
    const groupW = (group: Group, size: number) => (group.cross ? 3 * size + 2 * g : Math.min(2, group.items.length) * (size + g) - g)
    const groupH = (group: Group, size: number) =>
      group.cross ? 3 * size + 2 * g : Math.ceil(group.items.length / 2) * (size + g) - g
    // The play area keeps at least its height in width (or 60% of the screen): the columns get the rest,
    // and the buttons shrink to fit them, to 44 px at the least.
    const room = (cols - Math.min(rows, Math.round(cols * 0.6))) >> 1
    const least = Math.ceil(44 / px)
    while (b > least && (Math.max(groupW(spec.left, b), groupW(spec.right, b), pauseSize) + m + 2 > room ||
        groupH(spec.left, b) + pauseSize + 2 * m + g > rows)) b--
    const colW = Math.max(groupW(spec.left, b), groupW(spec.right, b), pauseSize)
    place(buttons, spec.left, m + ((colW - groupW(spec.left, b)) >> 1), rows - m - groupH(spec.left, b), b, g, false)
    place(buttons, spec.right, cols - m - colW + ((colW - groupW(spec.right, b)) >> 1), rows - m - groupH(spec.right, b), b, g, true)
    buttons.push({ bit: spec.pauseBit, glyph: 'pause', x: cols - m - pauseSize - ((colW - pauseSize) >> 1), y: m, w: pauseSize, h: pauseSize })
    const playX = m + colW + 2
    const playW = cols - 2 * playX
    L.hud = { x: playX, y: 0, w: playW, h: hudH }
    L.play = { x: playX, y: hudH, w: playW, h: rows - hudH }
  } else {
    // A bar along the bottom: the left group, the pause button, the right group.
    const tall = rows - cols > 3 * b // room for a cross under a square play area
    const crossLeft = !!spec.left.cross && tall
    if (spec.left.cross && !tall && !spec.right.items.length && spec.left.items.length === 4) {
      // No room for a cross: left and right for the left thumb, up and down for the right.
      spec = { left: { items: spec.left.items.slice(0, 2) }, right: { items: spec.left.items.slice(2) }, pauseBit: spec.pauseBit }
    }
    const count = (crossLeft ? 3 : spec.left.items.length) + spec.right.items.length
    while (b > 8 && count * b + (count + 2) * g + pauseSize + 2 * m > cols) b--
    const barH = (crossLeft ? 3 * b + 2 * g : b) + m + 2 * g
    const top = rows - barH + 2 * g
    if (crossLeft) place(buttons, spec.left, m, top, b, g, false)
    else placeRow(buttons, spec.left.items, m, top, b, g)
    const rightW = spec.right.items.length * (b + g) - g
    placeRow(buttons, spec.right.items, cols - m - rightW, top, b, g)
    const leftEnd = m + (crossLeft ? 3 * b + 2 * g : spec.left.items.length * (b + g) - g)
    const mid = (leftEnd + cols - m - rightW) >> 1
    buttons.push({ bit: spec.pauseBit, glyph: 'pause', x: mid - (pauseSize >> 1), y: top + ((barH - m - 2 * g - pauseSize) >> 1),
      w: pauseSize, h: pauseSize })
    L.hud = { x: 0, y: 0, w: cols, h: hudH }
    L.play = { x: 0, y: hudH, w: cols, h: rows - hudH - barH }
  }
  L.buttons = buttons
  drawnHeld = -1
}

function placeRow(buttons: Button[], items: { bit: number; glyph: string }[], x: number, y: number, b: number, g: number) {
  for (let i = 0; i < items.length; i++) buttons.push({ bit: items[i].bit, glyph: items[i].glyph, x: x + i * (b + g), y, w: b, h: b })
}

// A group in a column: a cross (up, left, right, down in its items' order: left, right, up, down), or two a
// row, filled from the bottom row up (`fromRight` puts a lone last one on the right).
function place(buttons: Button[], group: Group, x: number, y: number, b: number, g: number, fromRight: boolean) {
  const items = group.items
  if (group.cross) {
    const at = [[0, 1], [2, 1], [1, 0], [1, 2]]
    for (let i = 0; i < items.length && i < 4; i++) {
      buttons.push({ bit: items[i].bit, glyph: items[i].glyph, x: x + at[i][0] * (b + g), y: y + at[i][1] * (b + g), w: b, h: b })
    }
    return
  }
  const lines = Math.ceil(items.length / 2)
  for (let i = 0; i < items.length; i++) {
    const line = (i / 2) | 0
    const alone = items.length % 2 === 1 && i === items.length - 1
    const col = alone ? (fromRight || items.length === 1 ? (items.length === 1 ? 0 : 1) : 0) : i % 2
    buttons.push({ bit: items[i].bit, glyph: items[i].glyph, x: x + col * (b + g), y: y + (lines - 1 - line) * (b + g), w: b, h: b })
  }
}

/** The button under cell (x, y), or null. Each takes a little of the gap around it. */
export function buttonAt(x: number, y: number): Button | null {
  const buttons = L.buttons
  for (let i = 0; i < buttons.length; i++) {
    const btn = buttons[i]
    const slack = (btn.w >> 3) + 1
    if (x >= btn.x - slack && x < btn.x + btn.w + slack && y >= btn.y - slack && y < btn.y + btn.h + slack) return btn
  }
  return null
}

/** Whether a finger moving from one button to another carries the press along (the D-pad's). */
export function slides(bit: number): boolean {
  return (bit & DIRS) !== 0
}

/** True when cell (x, y) is in the play area. */
export function inPlay(x: number, y: number): boolean {
  const p = L.play
  return x >= p.x && y >= p.y && x < p.x + p.w && y < p.y + p.h
}

let drawnHeld = -1

/** The bars or columns around the play area and every button: on a screen change. */
export function drawControls(cells: Uint8Array, held: number) {
  if (!L.controls) return
  const cols = L.cols
  const rows = L.rows
  const p = L.play
  if (L.side) {
    rect(cells, cols, rows, 0, 0, p.x, rows, UI.BAR)
    rect(cells, cols, rows, p.x + p.w, 0, cols - p.x - p.w, rows, UI.BAR)
    rect(cells, cols, rows, p.x - 1, 0, 1, rows, UI.SEP)
    rect(cells, cols, rows, p.x + p.w, 0, 1, rows, UI.SEP)
    // The game's name at the top of the left column, a word a line, where it fits.
    const words = L.name.split(' ')
    let y = Math.ceil(24 / L.px)
    for (const word of words) {
      const w = textWidth(word, L.ts)
      if (w > p.x - 4) break
      drawText(cells, cols, rows, word, (p.x - w) >> 1, y, L.ts, UI.HUD_DIM)
      y += 7 * L.ts
    }
  } else {
    const top = p.y + p.h
    rect(cells, cols, rows, 0, top, cols, rows - top, UI.BAR)
    rect(cells, cols, rows, 0, top, cols, 1, UI.SEP)
  }
  drawnHeld = -1
  updateControls(cells, held)
}

/** Draws again the buttons whose pressed look changed. Cheap: nothing when nothing did. */
export function updateControls(cells: Uint8Array, held: number) {
  if (!L.controls || held === drawnHeld) return
  const buttons = L.buttons
  for (let i = 0; i < buttons.length; i++) {
    const btn = buttons[i]
    const on = (held & btn.bit) !== 0
    if (drawnHeld >= 0 && on === ((drawnHeld & btn.bit) !== 0)) continue
    drawButton(cells, btn, on)
  }
  drawnHeld = held
}

function drawButton(cells: Uint8Array, btn: Button, on: boolean) {
  const cols = L.cols
  const rows = L.rows
  const r = btn.w >= 12 ? 2 : 1
  // An edge all round, darker below: the face sits up a cell until pressed.
  roundRect(cells, cols, rows, btn.x, btn.y, btn.w, btn.h, UI.BTN_EDGE, r)
  const lift = on ? 0 : 1
  roundRect(cells, cols, rows, btn.x + 1, btn.y + 1 + (on ? 1 : 0), btn.w - 2, btn.h - 3, on ? UI.BTN_ON : UI.BTN, r)
  const ink = on ? UI.BTN_INK_ON : UI.BTN_INK
  const glyph = btn.glyph
  if (glyph[0] === ':') {
    // A letter of the font.
    const text = glyph.slice(1)
    const s = Math.max(1, Math.floor((btn.w * 0.45) / 5))
    drawText(cells, cols, rows, text, btn.x + ((btn.w - textWidth(text, s)) >> 1), btn.y + ((btn.h - 5 * s) >> 1) - lift + 1, s, ink)
    return
  }
  const bits = GLYPHS[glyph]
  if (!bits) return
  const s = Math.max(1, Math.floor((btn.w * 0.5) / 8))
  const x0 = btn.x + ((btn.w - 8 * s) >> 1)
  const y0 = btn.y + ((btn.h - 8 * s) >> 1) - lift + 1
  for (let j = 0; j < 8; j++) {
    for (let i = 0; i < 8; i++) {
      if (bits.charCodeAt(j * 8 + i) === 35) rect(cells, cols, rows, x0 + i * s, y0 + j * s, s, s, ink)
    }
  }
}

sources.input.ts:
// Input from a touch screen, GPIO buttons and a keyboard, as one set of
// action bits. `held` is what is down now; `pressed` collects what went
// down since the game last looked, so a tap shorter than a frame still
// counts. Touches are tracked by pointerId, so two fingers can hold left
// and fire at once; a finger sliding across the D-pad carries the press to
// the button under it. A touch that starts outside the buttons is the
// game's (`touch`): a drag, a tap on the board.
import { L, buttonAt, slides } from './layout'

export const LEFT = 1
export const RIGHT = 2
export const UP = 4
export const DOWN = 8
export const A = 16
export const B = 32
export const C = 64
export const PAUSE = 128

// Names the "Buttons" setting can use; a game adds its own (turnleft, rotate...).
const NAMES: Record<string, number> = { left: LEFT, right: RIGHT, up: UP, down: DOWN, a: A, b: B, c: C, pause: PAUSE }

export function nameAction(name: string, bit: number) {
  NAMES[name] = bit
}

// The keyboard: arrows and WASD move, Space / Z / K is A, X / J is B, C / L is C, Enter / P / Escape pause.
const KEYS: Record<string, number> = {
  ArrowLeft: LEFT, KeyA: LEFT, ArrowRight: RIGHT, KeyD: RIGHT, ArrowUp: UP, KeyW: UP, ArrowDown: DOWN, KeyS: DOWN,
  Space: A, KeyZ: A, KeyK: A, KeyX: B, KeyJ: B, KeyC: C, KeyL: C,
  Enter: PAUSE, NumpadEnter: PAUSE, KeyP: PAUSE, Escape: PAUSE,
}

/** A key of the game's own, or another action for one of the keys above. */
export function mapKey(code: string, bit: number) {
  KEYS[code] = bit
}

export const input = {
  keys: 0, // held on the keyboard
  gpio: 0, // held GPIO buttons
  touchBits: 0, // held on-screen buttons
  pressed: 0, // went down since consumed
  doubled: 0, // a GPIO button's double press, since consumed
  combo: 0, // GPIO buttons held together, when the last of them lifted
  comboPeak: 0,
  sawKeyboard: false,
  sawTouch: false,
  sawGpio: false,
  // The game's touch: one finger outside the buttons.
  touchId: -1,
  touchX: 0, // in cells
  touchY: 0,
  touchDown: false,
  touchStarted: false, // went down since consumed
  touchEnded: false,
}

// Up to eight fingers on the buttons: their pointerId and the bit each holds.
const ids = new Int32Array(8).fill(-1)
const bits = new Int32Array(8)

export function held(): number {
  return input.keys | input.gpio | input.touchBits
}

/** What went down since the last call, and forget it. */
export function consume(): number {
  const p = input.pressed
  input.pressed = 0
  return p
}

/** Forgets every hold: on a screen change, so a finger left on a button does not run on. */
export function releaseAll() {
  ids.fill(-1)
  input.keys = 0
  input.gpio = 0
  input.touchBits = 0
  input.pressed = 0
  input.doubled = 0
  input.combo = 0
  input.comboPeak = 0
  input.touchDown = false
  input.touchId = -1
}

function touchBitsNow(): number {
  let t = 0
  for (let i = 0; i < 8; i++) if (ids[i] >= 0) t |= bits[i]
  return t
}

// "LEFT=left, RIGHT=right, KEY0=a": labels (or roles) to action bits, read again when the text changes.
let mapText = ''
let map: Record<string, number> = {}

export function setButtonMap(text: string) {
  if (text === mapText) return
  mapText = text
  map = {}
  const parts = String(text || '').split(/[,;\n]/)
  for (let i = 0; i < parts.length; i++) {
    const eq = parts[i].indexOf('=')
    if (eq < 0) continue
    const label = parts[i].slice(0, eq).trim().toLowerCase()
    const names = parts[i].slice(eq + 1).trim().toLowerCase().split(/[+ ]+/)
    let value = 0
    for (let n = 0; n < names.length; n++) value |= NAMES[names[n]] || 0
    if (label && value) map[label] = (map[label] || 0) | value
  }
}

function gpioBits(payload: any): number {
  const label = String(payload.label || '').toLowerCase()
  if (label && map[label]) return map[label]
  const role = String(payload.role || '').toLowerCase()
  return (role && map[role]) || 0
}

/** Takes one event. Returns what it was: 0 nothing of ours, 1 a press or release, 2 the game's touch. */
export function takeEvent(event: string, payload: any): number {
  const px = L.px || 1
  if (event === 'pointerDown') {
    if (payload.pointerType === 'touch') input.sawTouch = true
    const x = Math.floor(payload.x / px)
    const y = Math.floor(payload.y / px)
    const btn = buttonAt(x, y)
    const id = payload.pointerId | 0
    if (btn) {
      for (let i = 0; i < 8; i++) {
        if (ids[i] < 0 || ids[i] === id) {
          ids[i] = id
          bits[i] = btn.bit
          break
        }
      }
      input.touchBits = touchBitsNow()
      input.pressed |= btn.bit
      return 1
    }
    input.touchId = id
    input.touchX = x
    input.touchY = y
    input.touchDown = true
    input.touchStarted = true
    return 2
  }
  if (event === 'pointerMove') {
    const id = payload.pointerId | 0
    if (input.touchDown && id === input.touchId) {
      input.touchX = Math.floor(payload.x / px)
      input.touchY = Math.floor(payload.y / px)
      return 2
    }
    for (let i = 0; i < 8; i++) {
      if (ids[i] !== id || !slides(bits[i])) continue
      const btn = buttonAt(Math.floor(payload.x / px), Math.floor(payload.y / px))
      if (btn && btn.bit !== bits[i] && slides(btn.bit)) {
        bits[i] = btn.bit
        input.touchBits = touchBitsNow()
        input.pressed |= btn.bit
        return 1
      }
    }
    return 0
  }
  if (event === 'pointerUp' || event === 'pointerCancel') {
    const id = payload.pointerId | 0
    if (input.touchDown && id === input.touchId) {
      input.touchDown = false
      input.touchEnded = true
      input.touchId = -1
      return 2
    }
    let found = 0
    for (let i = 0; i < 8; i++) {
      if (ids[i] === id) {
        ids[i] = -1
        found = 1
      }
    }
    input.touchBits = touchBitsNow()
    return found
  }
  if (event === 'keyDown' || event === 'keyUp') {
    if (payload.ctrl || payload.meta || payload.alt) return 0
    const bit = KEYS[payload.code] || 0
    if (!bit) return 0
    input.sawKeyboard = true
    if (event === 'keyUp') {
      input.keys &= ~bit
      return 1
    }
    if (payload.repeat) return 0
    input.keys |= bit
    input.pressed |= bit
    return 1
  }
  if (event === 'gpio') {
    input.sawGpio = true
    const bit = gpioBits(payload)
    if (!bit) return 0
    if (payload.claimed) {
      // A key the frame took for itself (the voice chat's): let it go, and make nothing of the press.
      input.gpio &= ~bit
      input.comboPeak = 0
      return 0
    }
    if (payload.action === 'down') {
      input.gpio |= bit
      input.pressed |= bit
      input.comboPeak |= bit
    } else if (payload.action === 'up') {
      input.gpio &= ~bit
      if (!input.gpio) {
        input.combo = input.comboPeak
        input.comboPeak = 0
      }
    }
    return 1
  }
  if (event === 'button') {
    const bit = gpioBits(payload)
    if (!bit) return 0
    // Every frame that runs these games sends gpio edges too (they act on those); of what the button layer
    // makes of them, only a double press means more.
    if (payload.action === 'doublePress') {
      input.doubled |= bit
      return 1
    }
    return 0
  }
  return 0
}

sources.core.ts:
// The pieces every game's loop shares: a fixed-step clock, a seeded random
// number generator, the settings read at most once a second, and the
// high-score table.

// --- the clock: the game advances in whole steps of 1/60 s from Date.now(),
// so it runs at the same speed at 12 frames a second and at 40 ---
export const STEP_MS = 1000 / 60
let last = 0
let owed = 0

/** Steps due since the last call (at most 6: a long stall slows the game rather than jumping it). */
export function stepsDue(now: number): number {
  let d = last ? now - last : STEP_MS
  last = now
  if (d < 0) d = 0
  if (d > 100) d = 100
  owed += d
  let n = (owed / STEP_MS) | 0
  if (n > 6) n = 6
  owed -= n * STEP_MS
  if (owed > STEP_MS) owed = STEP_MS
  return n
}

/** Start counting from now: after a pause, a title, a fresh module. */
export function restartClock(now: number) {
  last = now
  owed = 0
}

// --- xorshift32: the same game from the same seed on every frame type ---
let seed = 1

export function setSeed(value: number) {
  seed = value | 0 || 0x9e3779b9
}

export function getSeed(): number {
  return seed
}

/** An integer in [0, n). */
export function rand(n: number): number {
  seed ^= seed << 13
  seed ^= seed >>> 17
  seed ^= seed << 5
  return ((seed >>> 0) % n) | 0
}

// --- settings: each read of app.state crosses into the runtime, so they are read at most once a second
// (and whenever `force`), never per frame ---
let settingsAt = -1e9
let settings: Record<string, any> = {}

export function readSettings(app: any, names: string[], now: number, force: boolean): Record<string, any> {
  if (!force && now - settingsAt < 1000) return settings
  settingsAt = now
  const state = app.state
  const next: Record<string, any> = {}
  for (let i = 0; i < names.length; i++) next[names[i]] = state[names[i]]
  settings = next
  return settings
}

/** High contrast: asked for, or automatic on a panel with no color. */
export function highContrast(contrast: any, frameColor: any): boolean {
  const mode = contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && frameColor === false)
}

// --- the high scores: the best five, kept in the scene's private `scores` field ---
export function readScores(raw: any): number[] {
  let list = raw
  if (typeof list === 'string') {
    try {
      list = JSON.parse(list)
    } catch (e) {
      list = null
    }
  }
  const out: number[] = []
  if (Array.isArray(list)) {
    for (let i = 0; i < list.length && out.length < 5; i++) {
      const v = Number(list[i])
      if (v > 0) out.push(Math.floor(v))
    }
  }
  out.sort((a, b) => b - a)
  return out
}

/** Puts `score` into the list where it belongs: its place (0 the best), or -1 when it did not make it. */
export function placeScore(list: number[], score: number): number {
  if (score <= 0) return -1
  let at = 0
  while (at < list.length && list[at] >= score) at++
  if (at >= 5) return -1
  list.splice(at, 0, score)
  if (list.length > 5) list.length = 5
  return at
}

sources.card.ts:
// The cards over the play area: the title, the pause card and game over. A
// card is lines of text, centered, in a box with an edge; a line can be a
// key (a button on the card, tapped by its id). Drawn on screen changes only.
import { frame, rect, roundRect } from './gfx'
import { drawText, drawTextShadow, textWidth } from './font'
import { L } from './layout'
import { UI } from './palette'

export type Line = { text: string; scale?: number; ink?: number; key?: number; optional?: boolean; gap?: number; group?: number }

// The keys on the card showing: their ids and rectangles, for taps.
const keyIds: number[] = []
const keyRects: number[] = []

/** The card's lines in a box over the play area. Lines marked optional go first when it is too short. */
export function drawCard(cells: Uint8Array, lines: Line[], fullScreen: boolean) {
  const cols = L.cols
  const rows = L.rows
  const ts = L.ts
  const area = fullScreen ? { x: 0, y: 0, w: cols, h: rows } : L.play
  const pad = (fullScreen ? 6 : 3) * ts
  keyIds.length = 0
  keyRects.length = 0
  // Each line's scale, shrunk so it fits the width.
  const maxW = area.w - 2 * pad - 2
  // Lines too wide even at the smallest scale are wrapped at spaces.
  let shown: Line[] = []
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n]
    if (!line.text || line.key || textWidth(line.text, ts) <= maxW) {
      shown.push(line)
      continue
    }
    let current = ''
    for (const word of line.text.split(' ')) {
      const next = current ? current + ' ' + word : word
      if (current && textWidth(next, ts) > maxW) {
        shown.push({ text: current, ink: line.ink, optional: line.optional, group: n + 1 })
        current = word
      } else {
        current = next
      }
    }
    if (current) shown.push({ text: current, ink: line.ink, optional: line.optional, group: n + 1 })
  }
  const scaleOf = (line: Line) => {
    let s = (line.scale || 1) * ts
    while (s > ts && textWidth(line.text, s) + (line.key ? 4 * ts : 0) > maxW) s--
    return s
  }
  const heightOf = (line: Line) => {
    if (!line.text) return (line.gap || 3) * ts
    return 5 * scaleOf(line) + (line.key ? 4 * ts : 0) + 2 * ts
  }
  let total = 0
  for (const line of shown) total += heightOf(line)
  while (total + 2 * pad > area.h && shown.some((line) => line.optional)) {
    // Drop the last optional line (all of it, when it was wrapped).
    for (let i = shown.length - 1; i >= 0; i--) {
      if (shown[i].optional) {
        const group = shown[i].group
        for (let j = i; j >= 0 && (j === i || (group && shown[j].group === group)); j--) {
          total -= heightOf(shown[j])
          shown.splice(j, 1)
        }
        break
      }
    }
  }
  let width = 0
  for (const line of shown) {
    const w = textWidth(line.text, scaleOf(line)) + (line.key ? 8 * ts : 0)
    if (w > width) width = w
  }
  const boxW = Math.min(area.w - 2, width + 2 * pad + 2)
  const boxH = Math.min(area.h - 2, total + 2 * pad - 2 * ts)
  const x = area.x + ((area.w - boxW) >> 1)
  const y = area.y + ((area.h - boxH) >> 1)
  if (!fullScreen) {
    rect(cells, cols, rows, x + ts, y + ts, boxW, boxH, UI.CARD_SHADOW)
    rect(cells, cols, rows, x, y, boxW, boxH, UI.CARD)
    frame(cells, cols, rows, x, y, boxW, boxH, UI.CARD_EDGE, ts)
  } else {
    rect(cells, cols, rows, 0, 0, cols, rows, UI.CARD)
  }
  let top = y + pad
  const cx = x + (boxW >> 1)
  for (const line of shown) {
    if (!line.text) {
      top += (line.gap || 3) * ts
      continue
    }
    const s = scaleOf(line)
    const w = textWidth(line.text, s)
    if (line.key) {
      const kw = w + 8 * ts
      const kh = 5 * s + 4 * ts
      roundRect(cells, cols, rows, cx - (kw >> 1), top, kw, kh, UI.CARD_KEY, ts > 1 ? 2 : 1)
      drawText(cells, cols, rows, line.text, cx - (w >> 1), top + 2 * ts, s, UI.CARD_KEY_INK)
      keyIds.push(line.key)
      keyRects.push(cx - (kw >> 1), top, kw, kh)
      top += kh + 2 * ts
      continue
    }
    const ink = line.ink === undefined ? UI.CARD_INK : line.ink
    if (s >= 2 * ts) drawTextShadow(cells, cols, rows, line.text, cx - (w >> 1), top, s, ink, UI.CARD_SHADOW)
    else drawText(cells, cols, rows, line.text, cx - (w >> 1), top, s, ink)
    top += 5 * s + 2 * ts
  }
}

/** The key of the card under cell (x, y), or 0. */
export function cardKeyAt(x: number, y: number): number {
  for (let i = 0; i < keyIds.length; i++) {
    const kx = keyRects[i * 4]
    const ky = keyRects[i * 4 + 1]
    if (x >= kx - 2 && y >= ky - 2 && x < kx + keyRects[i * 4 + 2] + 2 && y < ky + keyRects[i * 4 + 3] + 2) return keyIds[i]
  }
  return 0
}

export function forgetCardKeys() {
  keyIds.length = 0
  keyRects.length = 0
}

/** The high-score lines for a card: the best five, `mark` (a place) shown with arrows. */
export function scoreLines(scores: number[], mark: number): Line[] {
  const lines: Line[] = [{ text: 'HIGH SCORES', ink: UI.CARD_DIM, optional: true }]
  if (!scores.length) lines.push({ text: 'NONE YET', ink: UI.CARD_DIM, optional: true })
  for (let i = 0; i < scores.length; i++) {
    const text = i + 1 + '. ' + pad6(scores[i])
    lines.push({ text: i === mark ? '>' + text + '<' : text, ink: i === mark ? UI.CARD_HI : UI.CARD_INK, optional: true })
  }
  return lines
}

function pad6(n: number): string {
  let s = String(n)
  while (s.length < 6) s = ' ' + s
  return s
}

/** The HUD strip's background, on a screen change. */
export function drawHudBar(cells: Uint8Array) {
  const h = L.hud
  rect(cells, L.cols, L.rows, h.x, h.y, h.w, h.h, UI.HUD_BG)
}

/** The HUD's three places: left, middle and right, each as wide as the widest text it will hold (the
 *  templates given). One that does not fit gets no width and is not drawn. */
export const HUD = { lx: 0, lw: 0, mx: 0, mw: 0, rx: 0, rw: 0 }

export function hudSlots(left: string, mid: string, right: string) {
  const h = L.hud
  const ts = L.ts
  HUD.lx = h.x + 2 * ts
  HUD.lw = textWidth(left, ts)
  HUD.rw = textWidth(right, ts)
  HUD.rx = h.x + h.w - 2 * ts - HUD.rw
  if (HUD.rx < HUD.lx + HUD.lw + 2 * ts) HUD.rw = 0
  const mw = textWidth(mid, ts)
  const from = HUD.lx + HUD.lw + 3 * ts
  const to = HUD.rw ? HUD.rx - 3 * ts : h.x + h.w - 2 * ts
  HUD.mw = mid && to - from >= mw ? mw : 0
  HUD.mx = (from + to - mw) >> 1
}

/** One HUD field: `label` dim and `value` bright, in the place at x, `width` cells wide (cleared first);
 *  `right` aligns it to the right of the place. Nothing when the place has no width. */
export function hudField(cells: Uint8Array, x: number, width: number, label: string, value: string, right?: boolean) {
  if (width <= 0) return
  const h = L.hud
  const ts = L.ts
  const y = h.y + 2
  rect(cells, L.cols, L.rows, x, y, width, 5 * ts, UI.HUD_BG)
  const lw = label ? textWidth(label, ts) + 5 * ts : 0
  const at = right ? x + width - lw - textWidth(value, ts) : x
  drawText(cells, L.cols, L.rows, label, at, y, ts, UI.HUD_DIM)
  drawText(cells, L.cols, L.rows, value, at + lw, y, ts, UI.HUD_INK)
}
